 perform set_config('app.customer_id','55004000-0000-4000-8000-000000000001',true),set_config('app.assignment_id',a::text,true),set_config('app.membership_id',m::text,true),set_config('app.identity_id',i::text,true),set_config('app.correlation_id','55004000-0000-4000-8000-000000000099',true);
end $$;
