create temporary table planning_roles(name text primary key,id uuid);
insert into planning_roles values ('principal',public.phase3_grant_mandate('{"membershipId":"55004000-0000-4000-8000-000000000021","function":"rektor","scopeKind":"school","unitIds":["55004000-0000-4000-8000-000000000030"]}'));
insert into planning_roles values ('principal2',public.phase3_grant_mandate('{"membershipId":"55004000-0000-4000-8000-000000000022","function":"rektor","scopeKind":"school","unitIds":["55004000-0000-4000-8000-000000000030"]}'));
select pg_temp.planning_actor((select id from planning_roles where name='principal'),'55004000-0000-4000-8000-000000000021','55004000-0000-4000-8000-000000000011');
insert into planning_roles values ('admin',public.phase3_grant_mandate('{"membershipId":"55004000-0000-4000-8000-000000000023","function":"administrator","scopeKind":"school","unitIds":["55004000-0000-4000-8000-000000000030"]}'));
