insert into public.app_sessions(id,token_hash,identity_id,membership_id,assignment_id,expires_at,absolute_expires_at)
 values('55004000-0000-4000-8000-000000000080',decode(md5('55004000-0000-4000-8000-000000000080')||md5('55004000-0000-4000-8000-000000000080'),'hex'),'55004000-0000-4000-8000-000000000011','55004000-0000-4000-8000-000000000021',(select id from planning_roles where name='principal'),clock_timestamp()+interval '1 hour',clock_timestamp()+interval '8 hours');
-- Grants är synliga endast i denna återställande provtransaktion.
grant execute on function public.phase5_read_timplan(uuid), public.phase5_change_timplan_cell(uuid,integer,text,integer,integer) to skolplattform_worker;
select pg_temp.planning_actor((select id from planning_roles where name='principal'),'55004000-0000-4000-8000-000000000021','55004000-0000-4000-8000-000000000011');
set local role skolplattform_worker;
select throws_ok($q$select public.phase5_read_timplan('55004000-0000-4000-8000-000000000050')$q$,'55000',null,'Worker cannot read without actual session');
select throws_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',0,'matematik',0,101)$q$,'55000',null,'missing Worker session rolls back changed cell');
select set_config('app.session_id','55004000-0000-4000-8000-000000000080',true);
select lives_ok($q$select public.phase5_read_timplan('55004000-0000-4000-8000-000000000050')$q$,'Worker reads with actual session');
select lives_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',0,'matematik',0,101)$q$,'Worker changes with actual session');
reset role;
select is((select revision from public.timplans where id='55004000-0000-4000-8000-000000000050'),1,'missing-session write left no revision');
select is((select count(*) from public.security_events where object_id='55004000-0000-4000-8000-000000000050'),2::bigint,'only successful read and change have DB event');
select ok((select bool_and(source='db' and session_id='55004000-0000-4000-8000-000000000080' and actor_identity_id='55004000-0000-4000-8000-000000000011' and membership_id='55004000-0000-4000-8000-000000000021' and assignment_id=(select id from planning_roles where name='principal') and correlation_id='55004000-0000-4000-8000-000000000099' and details='{}'::jsonb) from public.security_events where object_id='55004000-0000-4000-8000-000000000050'),'DB audit matches actual session context without cell values');
update public.app_sessions set identity_id='55004000-0000-4000-8000-000000000012',membership_id='55004000-0000-4000-8000-000000000022',assignment_id=(select id from planning_roles where name='principal2') where id='55004000-0000-4000-8000-000000000080';
select throws_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',1,'matematik',0,777)$q$,'55000',null,'foreign session identity stops and rolls back write');
update public.app_sessions set identity_id='55004000-0000-4000-8000-000000000011',membership_id='55004000-0000-4000-8000-000000000021',assignment_id=(select id from planning_roles where name='principal') where id='55004000-0000-4000-8000-000000000080';
update public.app_sessions set membership_id=null where id='55004000-0000-4000-8000-000000000080';
select throws_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',1,'matematik',0,777)$q$,'55000',null,'missing session membership stops and rolls back write');
update public.app_sessions set membership_id='55004000-0000-4000-8000-000000000021',identity_id='55004000-0000-4000-8000-000000000011' where id='55004000-0000-4000-8000-000000000080';
update public.app_sessions set assignment_id=null where id='55004000-0000-4000-8000-000000000080';
select throws_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',1,'matematik',0,777)$q$,'55000',null,'missing session assignment stops and rolls back write');
update public.app_sessions set assignment_id=(select id from planning_roles where name='principal') where id='55004000-0000-4000-8000-000000000080';
update public.app_sessions set revoked_at=clock_timestamp() where id='55004000-0000-4000-8000-000000000080';
select throws_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',1,'matematik',0,777)$q$,'55000',null,'revoked session stops and rolls back write');
update public.app_sessions set revoked_at=null where id='55004000-0000-4000-8000-000000000080';
update public.app_sessions set expires_at=clock_timestamp()-interval '1 minute' where id='55004000-0000-4000-8000-000000000080';
select throws_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',1,'matematik',0,777)$q$,'55000',null,'expired session stops and rolls back write');
update public.app_sessions set expires_at=clock_timestamp()+interval '1 hour' where id='55004000-0000-4000-8000-000000000080';
select set_config('app.session_id','55004000-0000-4000-8000-000000000999',true);
select throws_ok($q$select public.phase5_read_timplan('55004000-0000-4000-8000-000000000050')$q$,'55000',null,'nonexistent session rejected');
select set_config('app.session_id','55004000-0000-4000-8000-000000000080',true);
select set_config('app.correlation_id','',true);
select throws_ok($q$select public.phase5_read_timplan('55004000-0000-4000-8000-000000000050')$q$,'55000',null,'correlation required with session');
select set_config('app.correlation_id','55004000-0000-4000-8000-000000000099',true);
create function pg_temp.fail_audit_insert() returns trigger language plpgsql as $$begin
 if new.action='timplan_cell_changed' then raise exception 'Synthetic generic audit failure' using errcode='P0001'; end if; return new;
end $$;
create trigger planning_session_audit_failure before insert on public.security_events for each row execute function pg_temp.fail_audit_insert();
select throws_ok($q$select public.phase5_change_timplan_cell('55004000-0000-4000-8000-000000000050',1,'matematik',0,777)$q$,'55000',null,'generic INSERT error normalized to audit unavailable');
drop trigger planning_session_audit_failure on public.security_events;
select is((select revision from public.timplans where id='55004000-0000-4000-8000-000000000050'),1,'all failed session/audit calls preserve revision');
select is((select hours[1]::int from public.timplan_cells where timplan_id='55004000-0000-4000-8000-000000000050' and row_id='matematik'),101,'all failed session/audit calls preserve hours');
select is((select count(*) from public.security_events where object_id='55004000-0000-4000-8000-000000000050'),2::bigint,'failed session/audit calls add no successful event');
select is((select count(*) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname like 'phase5_%' and has_function_privilege('skolplattform_worker',p.oid,'execute')),3::bigint,'exactly three Worker entrypoints; helpers closed');
select is(has_function_privilege('anon','public.phase5_read_timplan(uuid)','execute'),false,'anon cannot call phase5_read_timplan');
select is(has_function_privilege('anon','public.phase5_change_timplan_cell(uuid,integer,text,integer,integer)','execute'),false,'anon cannot call phase5_change_timplan_cell');
select is(has_function_privilege('anon','public.phase5_timplan_scope(uuid,boolean)','execute'),false,'anon cannot call phase5_timplan_scope');
select is(has_function_privilege('anon','public.phase5_timplan_audit(uuid,text)','execute'),false,'anon cannot call phase5_timplan_audit');
select is(has_function_privilege('authenticated','public.phase5_read_timplan(uuid)','execute'),false,'authenticated cannot call phase5_read_timplan');
select is(has_function_privilege('authenticated','public.phase5_change_timplan_cell(uuid,integer,text,integer,integer)','execute'),false,'authenticated cannot call phase5_change_timplan_cell');
select is(has_function_privilege('authenticated','public.phase5_timplan_scope(uuid,boolean)','execute'),false,'authenticated cannot call phase5_timplan_scope');
select is(has_function_privilege('authenticated','public.phase5_timplan_audit(uuid,text)','execute'),false,'authenticated cannot call phase5_timplan_audit');
select * from finish();
rollback;
